#[allow(unused_variables, unused_mut)]
fn set_features_capnp_features_lists_params(mut b: crate::features_capnp::features::lists_params::Builder<'_>, inp: &mut dyn Input, path: &str) -> Result<(), CallError> {
    let p = join(path, "ints");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_ints(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            if let Some(v) = inp.int(&e0)? {
                l.set(i0, u8::try_from(v).map_err(|_| CallError::out_of_range(&e0, "u8"))?);
            }
        }
    }
    let p = join(path, "names");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_names(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            if let Some(v) = inp.text(&e0)? {
                l.set(i0, v.as_str());
            }
        }
    }
    let p = join(path, "points");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_points(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            set_features_capnp_point(l.reborrow().get(i0), inp, &e0)?;
        }
    }
    let p = join(path, "grid");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_grid(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            if let Some(n1) = inp.count(&e0)? {
                let mut l1 = l.reborrow().init(i0, n1);
                for i1 in 0..n1 {
                    let e1 = join(&e0, &i1.to_string());
                    if let Some(v) = inp.int(&e1)? {
                        l1.set(i1, i32::try_from(v).map_err(|_| CallError::out_of_range(&e1, "i32"))?);
                    }
                }
            }
        }
    }
    let p = join(path, "colours");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_colours(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            if let Some(ix) = inp.enumerant(&e0, &["red", "deep-blue", "green"])? {
                l.set(i0, match ix { 0 => crate::features_capnp::Colour::Red, 1 => crate::features_capnp::Colour::DeepBlue, 2 => crate::features_capnp::Colour::Green, _ => return Err(CallError::at(&e0, ErrorKind::BadValue("enumerant".into()))) });
            }
        }
    }
    Ok(())
}

