#[allow(unused_variables, unused_mut)]
fn set_features_capnp_line(mut b: crate::features_capnp::line::Builder<'_>, inp: &mut dyn Input, path: &str) -> Result<(), CallError> {
    let p = join(path, "width");
    if let Some(v) = inp.int(&p)? {
        b.set_width(u16::try_from(v).map_err(|_| CallError::out_of_range(&p, "u16"))?);
    }
    let p = join(path, "opacity");
    if let Some(v) = inp.float(&p)? {
        b.set_opacity(v as f32);
    }
    let p = join(path, "name");
    if let Some(v) = inp.text(&p)? {
        b.set_name(v.as_str());
    }
    let p = join(path, "colour");
    if let Some(ix) = inp.enumerant(&p, &["red", "deep-blue", "green"])? {
        b.set_colour(match ix { 0 => crate::features_capnp::Colour::Red, 1 => crate::features_capnp::Colour::DeepBlue, 2 => crate::features_capnp::Colour::Green, _ => return Err(CallError::at(&p, ErrorKind::BadValue("enumerant".into()))) });
    }
    let p = join(path, "from");
    if inp.has(&p) { set_features_capnp_line_from(b.reborrow().init_from(), inp, &p)?; }
    let p = join(path, "to");
    if inp.has(&p) { set_features_capnp_line_to(b.reborrow().init_to(), inp, &p)?; }
    Ok(())
}

