#[allow(unused_variables, unused_mut)]
fn set_features_capnp_shape(mut b: crate::features_capnp::shape::Builder<'_>, inp: &mut dyn Input, path: &str) -> Result<(), CallError> {
    if [inp.has(&join(path, "circle")), inp.has(&join(path, "box")), inp.has(&join(path, "nothing")), inp.has(&join(path, "names"))].iter().filter(|x| **x).count() > 1 { return Err(CallError::union_twice(path)); }
    let p = join(path, "label");
    if let Some(v) = inp.text(&p)? {
        b.set_label(v.as_str());
    }
    let p = join(path, "circle");
    if let Some(v) = inp.int(&p)? {
        b.set_circle(u32::try_from(v).map_err(|_| CallError::out_of_range(&p, "u32"))?);
    }
    let p = join(path, "box");
    if inp.has(&p) { set_features_capnp_point(b.reborrow().init_box(), inp, &p)?; }
    let p = join(path, "nothing");
    if inp.has(&p) { b.set_nothing(()); }
    let p = join(path, "names");
    if let Some(n) = inp.count(&p)? {
        let mut l = b.reborrow().init_names(n);
        for i0 in 0..n {
            let e0 = join(&p, &i0.to_string());
            if let Some(v) = inp.text(&e0)? {
                l.set(i0, v.as_str());
            }
        }
    }
    Ok(())
}

