#[allow(unused_variables, unused_mut)]
fn out_features_capnp_node(r: crate::features_capnp::node::Reader<'_>, name: &str, out: &mut dyn Output) -> Result<(), CallError> {
    out.begin_struct(name, "Node");
    out.field("name", Value::Text(r.get_name()?.to_str()?));
    {
        let l = r.get_children()?;
        out.begin_list("children", "Node");
        for item in l.iter() {
            out_features_capnp_node(item, "", out)?;
        }
        out.end();
    }
    out.end();
    Ok(())
}

