fn out_features_capnp_page(r: crate::features_capnp::page::Reader<'_>, name: &str, out: &mut dyn Output) -> Result<(), CallError> {
    out.begin_struct(name, "Page");
    {
        let l = r.get_shapes()?;
        out.begin_list("shapes", "Shape");
        for item in l.iter() {
            out_features_capnp_shape(item, "", out)?;
        }
        out.end();
    }
    out.field("next", Value::Data(r.get_next()?));
    out.end();
    Ok(())
}

